import networkx as nx
import itertools

G = nx.Graph()
G.add_nodes_from(range(11))
G.add_edges_from([(2,8), (2,6), (2,10), (3,8), (0,10)])

for r in range(1, 6):
    for combo in itertools.combinations(range(11), r):
        if all(1 <= G.degree(node) <= 5 for node in combo):
            G.add_edges_from(itertools.combinations(combo, 2))
            if all(1 <= G.degree(node) <= 5 for node in G.nodes):
                edges = [(u, v) for u, v in G.edges if u < v]
                print(edges)
                break
    else:
        continue
    break
else:
    print("UNSATISFIABLE")
